/* @autogenerated */
package net.civeira.phylax.feature.oauth.delegatelogin.infrastructure.driven;

import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.ArgumentMatchers;
import org.mockito.Mockito;

import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProviderAccountLinkPolicyOptions;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProviderProviderTypeOptions;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.gateway.TenantLoginProviderQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserCommandRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserFilter;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.FederatedUser;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.gateway.FederatedIdentityGateway;
import net.civeira.phylax.feature.oauth.user.infrastructure.ActiveUserFindService;

class DelegatedAccessAuthValidatorAdapterUnitTest {
  private static final String PROVIDER = "corp";
  private static final String PROVIDER_UID = "lp-1";

  private ActiveUserFindService actives = Mockito.mock(ActiveUserFindService.class);
  private UserCommandRepositoryGateway users = Mockito.mock(UserCommandRepositoryGateway.class);
  private TenantLoginProviderQueryRepositoryGateway providers =
      Mockito.mock(TenantLoginProviderQueryRepositoryGateway.class);
  private FederatedIdentityGateway identities = Mockito.mock(FederatedIdentityGateway.class);
  private Tenant tenant = Mockito.mock(Tenant.class);
  private TenantLoginProvider loginProvider = Mockito.mock(TenantLoginProvider.class);
  private AuthRequest request = AuthRequest.builder().tenant("acme").build();
  private DelegatedAccessAuthValidatorAdapter adapter;

  @BeforeEach
  void setUp() {
    Mockito.reset(actives, users, providers, identities, tenant, loginProvider);
    Mockito.when(tenant.getUid()).thenReturn("t1");
    Mockito.when(tenant.getName()).thenReturn("acme");
    Mockito.when(actives.findEnabledTenant(ArgumentMatchers.eq("acme"), ArgumentMatchers.any()))
        .thenReturn(Optional.of(tenant));
    Mockito.when(actives.checkEnabled(ArgumentMatchers.any())).thenReturn(true);
    Mockito.when(loginProvider.getUid()).thenReturn(PROVIDER_UID);
    Mockito.when(loginProvider.getName()).thenReturn(PROVIDER);
    Mockito.when(loginProvider.isEnabled()).thenReturn(true);
    Mockito.when(loginProvider.getProviderType())
        .thenReturn(TenantLoginProviderProviderTypeOptions.SAML);
    Mockito.when(loginProvider.isUsersEnabledByDefault()).thenReturn(true);
    policy(TenantLoginProviderAccountLinkPolicyOptions.VERIFIED_EMAIL);
    Mockito.when(providers.list(ArgumentMatchers.any())).thenReturn(List.of(loginProvider));
    Mockito.when(users.findForUpdate(ArgumentMatchers.any())).thenReturn(Optional.empty());
    adapter = new DelegatedAccessAuthValidatorAdapter(actives, users, providers, identities);
  }

  private void policy(TenantLoginProviderAccountLinkPolicyOptions policy) {
    Mockito.when(loginProvider.getAccountLinkPolicy()).thenReturn(policy);
  }

  private User user(String uid, String name, String tenantUid) {
    User user = Mockito.mock(User.class);
    Mockito.when(user.getUid()).thenReturn(uid);
    Mockito.when(user.getName()).thenReturn(name);
    Mockito.when(user.getTenant()).thenReturn(TenantReference.of(tenantUid));
    Mockito.when(user.getFederatedProvider()).thenReturn(Optional.empty());
    Mockito.when(users.retrieveForUpdate(ArgumentMatchers.eq(uid), ArgumentMatchers.any()))
        .thenReturn(Optional.of(user));
    return user;
  }

  private static FederatedUser identity(String email, boolean verified) {
    return FederatedUser.builder().subject("sub-1").email(email).emailVerified(verified)
        .name("admin").build();
  }

  @Test
  @DisplayName("a linked subject enters its account whatever email it brings")
  void test_linked_subject() {
    user("u1", "alice@example.com", "t1");
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.of("u1"));

    Assertions.assertEquals(Optional.of("alice@example.com"),
        adapter.resolveAccount(request, PROVIDER, identity("other@example.com", false)));
    Mockito.verify(users, Mockito.never()).findForUpdate(ArgumentMatchers.any());
  }

  @Test
  @DisplayName("a link to an account of another tenant is ignored")
  void test_linked_other_tenant() {
    user("u1", "alice@example.com", "t2");
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.of("u1"));
    policy(TenantLoginProviderAccountLinkPolicyOptions.MANUAL);

    Assertions.assertTrue(
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", true)).isEmpty());
  }

  @Test
  @DisplayName("manual policy only accepts existing links")
  void test_manual() {
    policy(TenantLoginProviderAccountLinkPolicyOptions.MANUAL);
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.empty());

    Assertions.assertTrue(
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", true)).isEmpty());
    Mockito.verify(identities, Mockito.never()).link(ArgumentMatchers.any(), ArgumentMatchers.any(),
        ArgumentMatchers.any());
  }

  @Test
  @DisplayName("an unverified email never selects or creates an account")
  void test_unverified() {
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.empty());

    Assertions.assertTrue(
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", false)).isEmpty());
    Mockito.verify(users, Mockito.never()).findForUpdate(ArgumentMatchers.any());
  }

  @Test
  @DisplayName("an existing account is found by verified email, never by display name")
  void test_existing_by_email() {
    User alice = user("u1", "alice@example.com", "t1");
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.empty());
    Mockito.when(users.findForUpdate(ArgumentMatchers.any())).thenReturn(Optional.of(alice));
    Mockito.when(identities.link(PROVIDER_UID, "sub-1", "u1")).thenReturn("u1");

    Assertions.assertEquals(Optional.of("alice@example.com"),
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", true)));
    ArgumentCaptor<UserFilter> filter = ArgumentCaptor.forClass(UserFilter.class);
    Mockito.verify(users).findForUpdate(filter.capture());
    Assertions.assertEquals(Optional.of("alice@example.com"), filter.getValue().getName());
  }

  @Test
  @DisplayName("none policy does not join an account created by other means")
  void test_none_policy() {
    policy(TenantLoginProviderAccountLinkPolicyOptions.NONE);
    User alice = user("u1", "alice@example.com", "t1");
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.empty());
    Mockito.when(users.findForUpdate(ArgumentMatchers.any())).thenReturn(Optional.of(alice));

    Assertions.assertTrue(
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", true)).isEmpty());
  }

  @Test
  @DisplayName("a concurrent first access keeps the account that linked first")
  void test_concurrent_link() {
    User alice = user("u1", "alice@example.com", "t1");
    user("u2", "winner@example.com", "t1");
    Mockito.when(identities.linkedUser(PROVIDER_UID, "sub-1")).thenReturn(Optional.empty());
    Mockito.when(users.findForUpdate(ArgumentMatchers.any())).thenReturn(Optional.of(alice));
    Mockito.when(identities.link(PROVIDER_UID, "sub-1", "u1")).thenReturn("u2");

    Assertions.assertEquals(Optional.of("winner@example.com"),
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", true)));
  }

  @Test
  @DisplayName("an unknown or disabled provider resolves nothing")
  void test_unknown_provider() {
    Assertions.assertTrue(
        adapter.resolveAccount(request, "other", identity("alice@example.com", true)).isEmpty());
    Mockito.when(loginProvider.isEnabled()).thenReturn(false);
    Assertions.assertTrue(
        adapter.resolveAccount(request, PROVIDER, identity("alice@example.com", true)).isEmpty());
  }
}
